24	/**
25	 * Extremely small EventEmitter (browser-friendly).
26	 * We avoid Node’s built-in dependency to keep the
27	 * public bundle lightweight.
28	 */
29	class Emitter {
30	  constructor() {
31	    this._listeners = Object.create(null);
32	  }
33	
34	  on(type, cb) {
35	    (this._listeners[type] ||= new Set()).add(cb);
36	    return () => this.off(type, cb);
37	  }
38	
39	  off(type, cb) {
40	    this._listeners[type]?.delete(cb);
41	  }
42	
43	  emit(type, payload) {
44	    if (!this._listeners[type]) return;
45	    for (const cb of this._listeners[type]) {
46	      try {
47	        cb(payload);
48	      } catch (err) {
49	        // Listener errors should *not* break the dispatcher
50	        console.error(`[Emitter] listener for "${type}" failed:`, err);
51	      }
52	    }
53	  }
