243	  static run(name, context = {}) {
244	    const cached = SCRIPT_CACHE.get(name);
245	    if (!cached) throw new Error(`Script "${name}" not found.`);
246	    const luaState = lauxlib.luaL_newstate();
247	    lualib.luaL_openlibs(luaState);
