250	    lua.lua_newtable(luaState); // create table
251	    Object.entries(context).forEach(([key, val]) => {
252	      lauxlib.lua_pushstring(luaState, key);
253	      switch (typeof val) {
254	        case 'number': lua.lua_pushnumber(luaState, val); break;
255	        case 'string': lua.lua_pushstring(luaState, val); break;
256	        default:       lua.lua_pushstring(luaState, safeJson(val));
257	      }
